contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(a != address(0));
        require(a != address(c));
        uint256 balA = c.balances(a); if (__ESBMC_reverted()) return;
        uint256 cBefore = address(c).balance;
        uint256 thisBefore = address(this).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 balAAfter = c.balances(a); if (__ESBMC_reverted()) return;
        uint256 cAfter = address(c).balance;
        uint256 thisAfter = address(this).balance;
        bool shouldRevert = (balA > cBefore);
        assert(reverted == shouldRevert && (reverted || (balAAfter == 0 && cAfter == cBefore - balA && thisAfter == thisBefore)));
    }
    receive() external payable {}
}

